-- 补齐福建高中复习系统中的Mg/Cu、氮循环、无机材料和课程标准18项学生必做实验。
-- 仅更新REVIEW知识卡；不修改独立小测站、quiz_sessions或学生作答记录。
begin;

update public.chem_knowledge_cards
set structured_content = $curriculum_gap_h3_inorganic${"skillId":"H3_INORGANIC","version":2,"intro":"元素化合物知识量大，但组织方式很少：先画元素价态阶梯，再给每一种物质贴上类别标签，最后用反应条件连接转化。这样遇到陌生物质也能推，而不是背孤立方程式。","overview":["三条主轴：元素价态决定氧化还原方向，物质类别决定酸碱/离子反应，条件决定具体产物。","金属主线常见Na、Mg、Al、Fe、Cu；非金属主线常见Cl、S、N、C、Si及其化合物。","制备、检验、除杂必须形成“试剂—操作—现象—结论”闭环，并排除干扰。","陌生转化先守恒中心元素，再用题给性质、价态和条件预测。","镁、铜不能只在工艺或电化学题中顺带出现：要分别建立“单质—氧化物/氢氧化物—盐溶液”的性质网络。","氮循环要把氮的固定、含氮物质转化和环境影响连成闭环；传统无机非金属材料要能由原料、过程、组成与用途辨认。"],"visualSummary":{"kind":"network","title":"常见元素价态—类别网络","center":"条件决定产物","groups":[{"label":"Al","items":["Al³⁺","Al(OH)₃","含铝酸根"]},{"label":"Fe","items":["Fe⁰/Fe²⁺/Fe³⁺","沉淀颜色","KSCN检验"]},{"label":"S","items":["SO₂多重性质","浓H₂SO₄","SO₄²⁻检验"]},{"label":"N","items":["NH₃/NH₄⁺","NO/NO₂","HNO₃"]},{"label":"C/Si","items":["CO₂阶段反应","SiO₂边界","资源冶炼"]}]},"sections":[{"title":"价态—类别—条件三维框架","summary":"每个反应都能在三条轴上定位。","items":[{"label":"价态轴","rule":"低价态常有还原性，高价态常有氧化性，中间价态可能兼有；具体强弱由物质和介质决定。","examples":["【示范：Fe的三条坐标轴】先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。"],"visualSteps":["价态轴","标价态","判物质类别","读反应条件","连接网络"]},{"label":"类别轴","rule":"氧化物、酸、碱、盐、单质各有通性；两性物质能在合适条件下与强酸和强碱反应。","examples":["【示范：Fe的三条坐标轴】先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。"],"visualSteps":["类别轴","标价态","判物质类别","读反应条件","连接网络"]},{"label":"条件轴","rule":"浓度、温度、酸碱介质、试剂用量、空气/光照可改变产物或反应程度。","examples":["【示范：Fe的三条坐标轴】先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。"],"visualSteps":["条件轴","标价态","判物质类别","读反应条件","连接网络"]},{"label":"网络轴","rule":"先守住中心元素，再看它从哪种价态和类别转到哪一种，方程式自然成为网络的连线。","examples":["【示范：Fe的三条坐标轴】先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。"],"visualSteps":["网络轴","标价态","判物质类别","读反应条件","连接网络"]}]},{"title":"常见金属主线","summary":"抓特征反应和价态转化，不背百科。","items":[{"label":"Na及其化合物","rule":"Na强还原性；Na₂O₂中O为-1；Na₂CO₃/NaHCO₃关注水解、热稳定性和转化。","examples":["【示范：Na、Al、Fe各抓一条主线】Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。"],"visualSteps":["Na及其化合物","结构性质","典型化合物","价态/两性转化","实验现象"]},{"label":"Al及其化合物","rule":"Al、Al₂O₃、Al(OH)₃具有典型两性；Al³⁺与OH⁻的少量/过量会出现沉淀生成与溶解。","examples":["【示范：Na、Al、Fe各抓一条主线】Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。"],"visualSteps":["Al及其化合物","结构性质","典型化合物","价态/两性转化","实验现象"]},{"label":"Fe及其化合物","rule":"Fe常见0、+2、+3价；Fe²⁺有还原性，Fe³⁺有氧化性，利用颜色、沉淀和KSCN等建立检验与转化。","examples":["【示范：Na、Al、Fe各抓一条主线】Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。"],"visualSteps":["Fe及其化合物","结构性质","典型化合物","价态/两性转化","实验现象"]},{"label":"金属制备与防护","rule":"活泼性决定冶炼方法的大方向；腐蚀防护从原电池电极反应解释。","examples":["【示范：Na、Al、Fe各抓一条主线】Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。"],"visualSteps":["金属制备与防护","结构性质","典型化合物","价态/两性转化","实验现象"]}]},{"title":"常见非金属主线","summary":"用氧化还原和酸碱性把族内物质连接起来。","items":[{"label":"Cl","rule":"Cl₂强氧化性，氯水多粒子共存，HClO负责氧化漂白和消毒；Cl⁻用酸化AgNO₃检验。","examples":["【示范：C、Si、N、S、Cl网络定位】C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。"],"visualSteps":["Cl","中心元素","常见价态","物质类别","条件与环境"]},{"label":"S","rule":"H₂S中S为-2、SO₂中+4、H₂SO₄中+6；SO₂兼有还原性、氧化性并具有特定漂白现象。","examples":["【示范：C、Si、N、S、Cl网络定位】C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。"],"visualSteps":["S","中心元素","常见价态","物质类别","条件与环境"]},{"label":"N","rule":"NH₃/NH₄⁺、N₂、NO/NO₂、HNO₃构成价态网络；NH₃制备检验、硝酸氧化性和氮氧化物转化常考。","examples":["【示范：C、Si、N、S、Cl网络定位】C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。"],"visualSteps":["N","中心元素","常见价态","物质类别","条件与环境"]},{"label":"C与Si","rule":"CO₂/碳酸盐平衡、CO还原性；SiO₂网络结构及无机非金属材料联系性质与用途。","examples":["【示范：C、Si、N、S、Cl网络定位】C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。"],"visualSteps":["C与Si","中心元素","常见价态","物质类别","条件与环境"]}]},{"title":"制备、检验和除杂","summary":"答案不能只写试剂名。","items":[{"label":"制备","rule":"选择原料和反应，控制条件，设计发生—净化—收集—尾气处理，兼顾安全和纯度。","examples":["【示范：Fe²⁺、Fe³⁺的检验和除杂】检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。"],"visualSteps":["制备","制备要防副反应","取样检验","先排干扰","选择性除杂"]},{"label":"检验","rule":"加入特异试剂，写操作和明显现象，再给不超出证据的结论。","examples":["【示范：Fe²⁺、Fe³⁺的检验和除杂】检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。"],"visualSteps":["检验","制备要防副反应","取样检验","先排干扰","选择性除杂"]},{"label":"除杂","rule":"除去杂质但不引入新杂质、不损失主体，试剂适量或过量后的处理要交代。","examples":["【示范：Fe²⁺、Fe³⁺的检验和除杂】检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。"],"visualSteps":["除杂","制备要防副反应","取样检验","先排干扰","选择性除杂"]},{"label":"鉴别","rule":"同一操作下产生不同现象，或设计最少步骤的顺序实验；先排除干扰。","examples":["【示范：Fe²⁺、Fe³⁺的检验和除杂】检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。"],"visualSteps":["鉴别","制备要防副反应","取样检验","先排干扰","选择性除杂"]}]},{"title":"陌生信息题的迁移","summary":"陌生名称不等于陌生规律。","items":[{"label":"读信息","rule":"把氧化性、溶解性、颜色、热稳定性或给定方程式标到物质节点上。","examples":["【示范：陌生钴化合物信息题】题给Co²⁺/Co³⁺颜色、电势或反应条件时，先抄出中心元素价态和物质类别；再判断氧化/还原、酸碱或配位变化，写方程式并用原子、电荷、电子守恒核验。"],"visualSteps":["读信息","读题给信息","映射熟悉模型","写反应","守恒校验"]},{"label":"守中心元素","rule":"跟踪目标元素在每一步的价态和去向，先判断反应类型。","examples":["【示范：陌生钴化合物信息题】题给Co²⁺/Co³⁺颜色、电势或反应条件时，先抄出中心元素价态和物质类别；再判断氧化/还原、酸碱或配位变化，写方程式并用原子、电荷、电子守恒核验。"],"visualSteps":["守中心元素","读题给信息","映射熟悉模型","写反应","守恒校验"]},{"label":"写并校验","rule":"根据介质和条件写方程式，再用电子、原子、电荷守恒核验。","examples":["【示范：陌生钴化合物信息题】题给Co²⁺/Co³⁺颜色、电势或反应条件时，先抄出中心元素价态和物质类别；再判断氧化/还原、酸碱或配位变化，写方程式并用原子、电荷、电子守恒核验。"],"visualSteps":["写并校验","读题给信息","映射熟悉模型","写反应","守恒校验"]}]},{"title":"铝：两性和少量—过量反应网络","summary":"把Al、Al³⁺、Al(OH)₃和含铝酸根放在同一张条件网络中。","items":[{"label":"铝单质的条件边界","rule":"Al易失电子但常温下表面有致密氧化膜；它能与合适的酸或强碱反应放出H₂，遇冷的浓硫酸、浓硝酸可发生钝化。","examples":["【示范：铝片先打磨再反应】未打磨铝片反应可能先出现诱导阶段，因为要先破坏氧化膜；与NaOH溶液反应时Al最终进入含铝酸根，H来自水，需用电子守恒配平。"],"visualSteps":["识别氧化膜","看酸碱与浓度","判断Al失电子","按条件写产物"]},{"label":"Al₂O₃与Al(OH)₃的两性","rule":"两性指在合适条件下既能与强酸反应，也能与强碱反应；不是与任意酸、任意碱都同样迅速反应。","examples":["【示范：Al(OH)₃的两条路】与酸：Al(OH)₃+3H⁺=Al³⁺+3H₂O；与强碱可写Al(OH)₃+OH⁻=[Al(OH)₄]⁻。"],"visualSteps":["先认两性物质","遇酸生成Al³⁺","遇强碱生成含铝酸根","检查介质"],"caution":"含铝酸根的具体表示按苏教版教材或题目给定形式书写。"},{"label":"Al³⁺与OH⁻的阶段反应","rule":"向Al³⁺溶液逐滴加OH⁻，先生成Al(OH)₃沉淀；OH⁻继续过量，沉淀溶解生成含铝酸根。反向滴加时局部过量会改变现象和阶段。","examples":["【示范：AlCl₃中滴NaOH至过量】先Al³⁺+3OH⁻=Al(OH)₃↓，再Al(OH)₃+OH⁻=[Al(OH)₄]⁻；沉淀量经历0→增多→最多→减少至0。"],"visualSteps":["少量OH⁻成沉淀","达到最大沉淀","过量OH⁻溶解","对应沉淀曲线"]}]},{"title":"铁：0、+2、+3价与检验闭环","summary":"每次反应同时追踪价态、颜色、沉淀和检验干扰。","items":[{"label":"Fe单质的价态由氧化剂决定","rule":"Fe与非氧化性酸通常生成Fe²⁺和H₂；与Cl₂等较强氧化剂反应常生成Fe³⁺；与盐溶液反应还要看氧化性和用量。","examples":["【示范：Fe分别与HCl和Cl₂反应】Fe+2H⁺=Fe²⁺+H₂↑；2Fe+3Cl₂点燃生成2FeCl₃。不能把“铁通常+2价”机械套到强氧化剂条件。"],"visualSteps":["辨认氧化剂强弱","确定Fe终价态","写电子转移","核对条件"]},{"label":"Fe²⁺与Fe³⁺相互转化","rule":"Fe²⁺遇合适氧化剂失电子生成Fe³⁺；Fe³⁺遇Fe、Cu、I⁻等还原剂时可得电子生成Fe²⁺，具体能否反应以已知强弱和题给事实为准。","examples":["【示范：Fe³⁺与Fe反应】2Fe³⁺+Fe=3Fe²⁺；同一元素同时出现0、+3价并归中到+2价，用电子守恒可快速确定1∶2。"],"visualSteps":["标0与+3价","判断归中方向","电子守恒定比例","得到Fe²⁺"]},{"label":"Fe(OH)₂制备、氧化和离子检验","rule":"制Fe(OH)₂要减少溶液和装置中的O₂；生成的浅色沉淀会迅速变灰绿并最终转为红褐色Fe(OH)₃。Fe³⁺可用SCN⁻显色检验，但要排除本底颜色和能改变价态的试剂。","examples":["【示范：观察Fe(OH)₂氧化】Fe²⁺+2OH⁻=Fe(OH)₂↓；4Fe(OH)₂+O₂+2H₂O=4Fe(OH)₃。用煮沸冷却的水、液封或导管伸入液面下可减小O₂干扰。"],"visualSteps":["隔绝O₂制备","生成Fe(OH)₂","记录颜色时间链","再用检验闭环"],"caution":"仅凭溶液颜色不能唯一认定Fe²⁺或Fe³⁺，检验必须有特征反应并考虑干扰。"}]},{"title":"硫：多价态、漂白和硫酸性质","summary":"把-2、0、+4、+6价沿电子转移连接，并把SO₂漂白与氧化漂白分开。","items":[{"label":"SO₂的酸性、还原性和氧化性","rule":"SO₂是酸性氧化物；S为+4中间价，既可被氧化到+6，又可被还原到0或-2。某个具体反应体现哪种性质，要看S的价态是否变化。","examples":["【示范：SO₂通入酸性KMnO₄】SO₂中S由+4升到+6，体现还原性；而SO₂+2H₂S=3S↓+2H₂O中，SO₂的S由+4降到0，体现氧化性。"],"visualSteps":["先认酸性氧化物","标S为+4","看升价或降价","判断还原性或氧化性"]},{"label":"SO₂漂白的边界","rule":"SO₂可与某些有色物质形成不稳定的无色物，漂白常可逆且有选择性；HClO、O₃、H₂O₂等主要靠氧化破坏发色结构，通常不可逆。","examples":["【示范：品红和石蕊的现象分工】SO₂使品红褪色可体现漂白性；使紫色石蕊变红首先体现酸性，不能把所有颜色变化都归为漂白。加热后颜色恢复可支持SO₂漂白的可逆性。"],"visualSteps":["先识别有色物","判断酸碱变色","再判断漂白","用恢复性区分机理"]},{"label":"浓硫酸与SO₄²⁻检验","rule":"浓硫酸具有吸水性、脱水性和强氧化性，三者要按物质变化区分；检验SO₄²⁻通常先加稀盐酸排除CO₃²⁻、SO₃²⁻等，再加BaCl₂观察白色沉淀。","examples":["【示范：铜与浓硫酸】Cu+2H₂SO₄(浓)加热生成CuSO₄、SO₂和H₂O，S由+6降到+4体现强氧化性；这不能推广到稀硫酸。"],"visualSteps":["判断浓稀条件","区分三种性质","检验先排干扰","现象支持有限结论"],"caution":"用Ba(NO₃)₂并先加硝酸时，酸性NO₃⁻可能氧化SO₃²⁻制造SO₄²⁻证据，需警惕试剂引入干扰。"}]},{"title":"氮：氨—铵盐—氮氧化物—硝酸","summary":"按-3、0、+2、+4、+5价连接氮元素主线，同时保留实验条件和安全。","items":[{"label":"NH₃的溶解、碱性与喷泉","rule":"NH₃极易溶于水，且与水建立平衡生成NH₄⁺和OH⁻。喷泉形成首先来自气体快速溶解造成压强差，酸碱反应可进一步促进吸收。","examples":["【示范：氨喷泉实验】烧瓶充满干燥NH₃，少量水进入后NH₃迅速溶解，瓶内压强降低，外界大气压把滴有指示剂的水压入形成喷泉；溶液显碱性使指示剂变色。"],"visualSteps":["NH₃快速溶解","瓶内压强下降","大气压推液体进入","碱性使指示剂变色"]},{"label":"NH₄⁺检验与NH₃制备","rule":"检验NH₄⁺要取样、加浓碱并加热，使其转化为NH₃，再用湿润红色石蕊试纸等确认；实验室可由铵盐与碱加热制氨，并选择合适干燥、收集和尾气处理。","examples":["【示范：检验NH₄Cl】NH₄⁺+OH⁻加热生成NH₃↑+H₂O；逸出气体使湿润红色石蕊试纸变蓝。不能只凭“闻到气味”下结论。"],"visualSteps":["取少量样品","加碱并加热","检验NH₃","写出检出结论"],"caution":"禁止把鼻孔凑近容器直接闻气味；若需辨气味，应使用规范扇闻并以特征试纸作主要证据。"},{"label":"NO、NO₂与硝酸","rule":"NO通常无色，遇O₂迅速生成红棕色NO₂；NO₂与水反应可生成HNO₃和NO。硝酸既显酸性又有强氧化性，与金属反应通常不放H₂，产物受浓度和条件影响。","examples":["【示范：NO遇空气】2NO+O₂=2NO₂；3NO₂+H₂O=2HNO₃+NO。观察到无色气体接触空气变红棕，可作为NO被氧化的证据链。"],"visualSteps":["先识别NO无色","遇O₂变NO₂","NO₂与水反应","连接到HNO₃"],"caution":"浓、稀硝酸与金属的产物不能脱离题设绝对化，陌生条件以题给信息为准。"}]},{"title":"碳、硅与金属资源：性质要落到流程","summary":"把阶段反应、结构性质和冶炼方法用于真实分离与资源利用。","items":[{"label":"CO₂与碳酸盐的阶段反应","rule":"CO₂与碱的产物由物质的量比决定：OH⁻足量时主要生成CO₃²⁻，CO₂继续过量可转为HCO₃⁻；碳酸盐与酸也常分阶段。","examples":["【示范：CO₂通入NaOH】先CO₂+2OH⁻=CO₃²⁻+H₂O；继续通入CO₂，CO₃²⁻+CO₂+H₂O=2HCO₃⁻。先定少量物质再确定终点。"],"visualSteps":["读少量过量","先生成CO₃²⁻","继续生成HCO₃⁻","按终点合并方程"]},{"label":"Si、SiO₂和硅酸盐","rule":"SiO₂由原子构成共价网络，不存在独立SiO₂分子；它是酸性氧化物但不与水直接生成硅酸，能与强碱反应，也能与HF发生特殊反应。","examples":["【示范：SiO₂与NaOH】SiO₂+2OH⁻=SiO₃²⁻+H₂O，体现酸性氧化物与碱反应；“酸性氧化物都与水反应”在SiO₂处不成立。"],"visualSteps":["先认共价网络","判断酸性氧化物","写与强碱反应","检查通性例外"],"caution":"HF与玻璃反应属于教材特殊事实，不能由一般酸性氧化物通性推出。"},{"label":"冶炼方法与资源流程","rule":"很活泼金属常用熔融电解，中等活泼金属常用还原法，较不活泼金属可用热分解等方法；具体流程还要看矿物形态、能耗、纯度和安全。","examples":["【示范：海水提镁】海水中的Mg²⁺先转为Mg(OH)₂沉淀，再与酸转为无水MgCl₂，最后电解熔融MgCl₂制Mg；水溶液电解不能直接得到Mg。"],"visualSteps":["富集目标离子","沉淀分离","转为无水熔盐","熔融电解制金属"]}]},{"title":"镁与铜：补齐金属性质网络","summary":"把Mg、Cu的单质、氧化物、氢氧化物和盐放在同一张价态—类别图中。","items":[{"label":"Mg：0价到+2价及反应条件","rule":"Mg是较活泼金属，反应中通常由0价失去2e⁻形成Mg²⁺。它能与酸反应放出H₂；点燃时可与O₂反应，炽热镁还可在CO₂中继续燃烧，因此不能用CO₂扑灭镁火。","examples":["【示范：镁在二氧化碳中燃烧】2Mg+CO₂点燃生成2MgO+C。Mg由0升到+2，C由+4降到0；先用电子守恒定2∶1，再核对Mg、C、O原子。"],"visualSteps":["Mg：0→+2","C：+4→0","2e⁻×2=4e⁻","核对产物"],"caution":"镁与水、酸或其他介质的反应速率和产物受温度、氧化膜、浓度影响，按题给条件判断。"},{"label":"Mg²⁺—Mg(OH)₂—MgO转化","rule":"Mg²⁺遇足量OH⁻生成难溶Mg(OH)₂；Mg(OH)₂与酸反应回到Mg²⁺，受热可分解为MgO和H₂O。海水提镁正是利用沉淀富集、酸化转盐、无水化和熔融电解。","examples":["【示范：镁盐的三步转化】Mg²⁺+2OH⁻=Mg(OH)₂↓；Mg(OH)₂+2H⁺=Mg²⁺+2H₂O；Mg(OH)₂受热生成MgO+H₂O。每一步分别属于沉淀、酸碱和分解。"],"visualSteps":["Mg²⁺沉淀","酸化溶解","受热成MgO","接入提镁流程"],"caution":"难溶不等于非电解质，也不等于“溶液中完全没有Mg²⁺”。"},{"label":"Cu：0价与+2价的性质闭环","rule":"Cu较不活泼，不能从稀盐酸、稀硫酸中置换H₂；可被Cl₂、Fe³⁺或具有氧化性的酸等氧化为Cu²⁺。CuO、Cu(OH)₂与酸反应生成Cu²⁺，Cu²⁺又可沉淀为Cu(OH)₂或被较活泼金属置换。","examples":["【示范：铜及其化合物网络】CuO+2H⁺=Cu²⁺+H₂O；Cu²⁺+2OH⁻=Cu(OH)₂↓；Fe+Cu²⁺=Fe²⁺+Cu。三条反应分别体现碱性氧化物、沉淀和金属置换。"],"visualSteps":["CuO遇酸","Cu²⁺生成蓝色沉淀","活泼金属置换Cu","回到Cu单质"],"caution":"Cu与浓硫酸、硝酸反应通常不放H₂；产物必须依据酸的氧化性、浓度和题给条件。"}]},{"title":"氮的固定与氮循环","summary":"从大气N₂出发，沿固定—同化—转化—回归追踪氮元素和价态。","items":[{"label":"氮的固定：把游离氮变成化合态氮","rule":"氮的固定是把大气中的N₂转化为含氮化合物的过程。自然固氮包括雷电等作用，生物固氮由固氮微生物完成，工业固氮的代表是合成氨；把化合态氮之间互相转化不叫固氮。","examples":["【示范：合成氨属于工业固氮】N₂+3H₂⇌2NH₃把0价氮转为−3价氮，因此属于氮的固定；NH₃转化为NH₄NO₃只是化合态氮之间转化，不属于再次固氮。"],"visualSteps":["起点必须是N₂","转成化合态氮","区分三类固氮","排除化合态互转"]},{"label":"氮循环：含氮物质在环境中迁移","rule":"氮循环可按“大气N₂→固定形成含氮物质→生物吸收同化→有机氮分解成铵态氮→进一步转化为硝态氮→部分回到N₂”建立物质流。高中题重在读流程、守氮元素和判断氧化还原方向。","examples":["【示范：由铵态氮到硝态氮】NH₄⁺中N为−3价，转为NO₃⁻中的+5价时氮被氧化；若流程最终生成N₂，则氮回到0价。先标价态再判断需要氧化剂或还原环境。"],"visualSteps":["画氮元素物流","标−3/0/+5价","判断升降","守恒总氮"],"caution":"具体微生物名称和大学生化机理不作记忆要求；陌生步骤按题给信息处理。"},{"label":"含氮物质的利用与环境边界","rule":"氮肥提高作物产量，但过量施用可能造成水体富营养化、地下水硝酸盐负荷增加等问题；NOₓ还与大气污染有关。评价方案要同时看氮利用率、排放、能耗和循环回收。","examples":["【示范：流程评价不能只看产率】若工艺把尾气中的NOₓ吸收并转成可利用硝酸盐，评价应写“减少含氮污染物排放并回收氮资源”，同时核对吸收剂消耗和副产物去向。"],"visualSteps":["识别氮源去向","检查NOₓ/硝酸盐","看回收利用","兼顾产率与环境"]}]},{"title":"传统无机非金属材料与资源利用","summary":"把原料、主要过程、材料组成和性能用途逐一对应。","items":[{"label":"陶瓷：黏土高温烧结","rule":"传统陶瓷以黏土等硅酸盐原料为主，经成型和高温烧结获得。其组成和结构复杂，通常不是一种纯净物；性能与原料配比、烧结温度和微观结构有关。","examples":["【示范：判断陶瓷材料】题干出现“黏土成型—高温烧制—耐高温、耐腐蚀”时，可沿原料和工艺识别为传统陶瓷；不能把成品只写成某一个硅酸盐化学式。"],"visualSteps":["黏土原料","成型","高温烧结","联系性能用途"]},{"label":"玻璃：熔融后冷却形成非晶态材料","rule":"普通钠钙玻璃常以石英砂、纯碱和石灰石等为原料高温熔制。玻璃通常是混合物和非晶态材料，不具有晶体那样的长程周期性；“透明”不能作为晶体的判据。","examples":["【示范：普通玻璃原料辨认】SiO₂提供硅氧骨架，Na₂CO₃和CaCO₃在高温过程中引入相应氧化物组分并放出CO₂。按原料—高温反应—非晶态成品三步作答。"],"visualSteps":["石英砂/纯碱/石灰石","高温熔制","冷却成非晶态","性质不等同于晶体"]},{"label":"水泥及材料评价","rule":"普通硅酸盐水泥主要以石灰石、黏土等为原料，经高温煅烧并配入适量调节材料制得；使用时与水发生复杂变化并逐渐硬化。材料题还要考虑能耗、CO₂排放、耐久性和固体废物资源化。","examples":["【示范：水泥生产的绿色评价】石灰石高温分解和燃料燃烧都会带来CO₂排放。若用合适工业固废替代部分原料，可从减少天然资源消耗和固废堆存评价，但仍需检验产品性能和有害成分。"],"visualSteps":["石灰石/黏土","高温煅烧","加水硬化","评价能耗与资源循环"],"caution":"不要求记忆水泥熟料的大学矿物组成；按教材和题给流程判断。"}]}],"workedExamples":[{"substance":"Fe的三条坐标轴","path":"先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。","labels":["标价态","判物质类别","读反应条件","连接网络"]},{"substance":"Na、Al、Fe各抓一条主线","path":"Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。","labels":["结构性质","典型化合物","价态/两性转化","实验现象"]},{"substance":"C、Si、N、S、Cl网络定位","path":"C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。","labels":["中心元素","常见价态","物质类别","条件与环境"]},{"substance":"Fe²⁺、Fe³⁺的检验和除杂","path":"检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。","labels":["制备要防副反应","取样检验","先排干扰","选择性除杂"]},{"substance":"陌生钴化合物信息题","path":"题给Co²⁺/Co³⁺颜色、电势或反应条件时，先抄出中心元素价态和物质类别；再判断氧化/还原、酸碱或配位变化，写方程式并用原子、电荷、电子守恒核验。","labels":["读题给信息","映射熟悉模型","写反应","守恒校验"]},{"substance":"Fe²⁺和Fe³⁺相互转化","path":"Fe²⁺失e⁻可变Fe³⁺，需氧化剂；Fe³⁺得e⁻可变Fe²⁺，需还原剂。检验Fe³⁺可用KSCN出现血红色，但该现象只能证明检出Fe³⁺。","labels":["价态轴","选氧化剂/还原剂","证据边界"]},{"substance":"Al³⁺中滴加NaOH至过量","path":"先Al³⁺+3OH⁻=Al(OH)₃↓；继续加OH⁻，两性氢氧化物溶解生成含铝酸根的溶液粒子。要根据苏教版题设采用相应表示式。","labels":["先沉淀","后溶解","少量过量"]},{"substance":"AlCl₃中滴加NaOH至过量","path":"先生成Al(OH)₃沉淀，达到最大后在过量OH⁻中转化为含铝酸根。用两段离子方程式和沉淀量曲线共同表示。","labels":["少量成沉淀","最大值","过量溶解","图式对应"]},{"substance":"隔绝空气制Fe(OH)₂","path":"先除去水和装置中的O₂，再让Fe²⁺与OH⁻接触；记录浅色—灰绿—红褐的时间变化，并用4Fe(OH)₂+O₂+2H₂O=4Fe(OH)₃解释。","labels":["排O₂","生成沉淀","时间序列","氧化方程"]},{"substance":"S、N两条价态网络","path":"S抓-2、0、+4、+6和SO₂双重氧化还原性；N抓-3、0、+2、+4、+5和NH₃、NO、NO₂、HNO₃。每条连线都标氧化剂/还原剂和条件。","labels":["标价态节点","连接代表物质","注明反应条件","用电子守恒"]},{"substance":"海水提镁的四步主线","path":"由Mg²⁺沉淀为Mg(OH)₂，酸化成MgCl₂，脱水得到无水熔盐，再熔融电解。每步写清目标元素在哪一相和为何不能跳步。","labels":["沉淀富集","转化氯化物","无水化","熔融电解"]},{"substance":"Mg—Cu双金属网络","path":"Mg抓0→+2及Mg²⁺—Mg(OH)₂—MgO；Cu抓0↔+2及CuO—Cu²⁺—Cu(OH)₂。每条连线标反应类型、试剂、现象和条件。","labels":["标价态","接类别节点","写条件","用现象校验"]},{"substance":"一张氮循环图","path":"以N₂为起点标出自然/生物/工业固氮，再连接NH₃/NH₄⁺、有机氮、NO₃⁻和回到N₂的路径；每一步守住氮元素并标价态变化。","labels":["N₂起点","固定","环境转化","回归N₂"]},{"substance":"陶瓷—玻璃—水泥对照","path":"陶瓷抓黏土和烧结，玻璃抓石英砂等原料与非晶态，水泥抓石灰石/黏土煅烧及加水硬化；最后从能耗、排放和循环利用评价。","labels":["原料","过程","结构/硬化","绿色评价"]}],"checkpoints":["我能为一种元素画出价态阶梯。","我能从类别通性预测反应而不是只背方程式。","我会把检验答案写成操作、现象、结论。","我能用题给信息解决陌生物质转化。","我能画出Al³⁺—Al(OH)₃—含铝酸根的少量过量网络。","我能用价态、沉淀和检验现象连接Fe、S、N的核心反应。","我能区分SO₂漂白、酸碱变色和氧化还原褪色。","我能把C、Si和金属冶炼知识放进阶段反应或资源流程中。","我能分别画出Mg和Cu的单质—氧化物/氢氧化物—盐转化网络。","我能区分氮的固定与化合态氮之间的转化，并用价态读氮循环。","我能由原料、工艺和结构辨认陶瓷、玻璃与水泥。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$curriculum_gap_h3_inorganic$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_INORGANIC' and skill_id = 'H3_INORGANIC';

update public.chem_knowledge_cards
set structured_content = $curriculum_gap_h3_experiment${"skillId":"H3_EXPERIMENT","version":2,"intro":"实验综合不是背装置，而是建立证据链：目的决定原理，原理决定装置和操作，操作产生现象，现象支持结论；最后检查干扰、安全和误差。","overview":["完整实验链：目的—原理—装置/试剂—操作—现象—结论—误差。","制备实验按发生、净化、干燥、收集、检验、尾气处理组织。","探究实验必须控制变量、设置对照、排除干扰，结论不得超过证据。","定量实验先写测量量与待求量关系，再判断误差如何传递。","安全优先：气密性、防倒吸、防爆沸、有毒气体处理和规范加热。","课程标准列出的18个学生必做实验必须逐个有入口；每个入口都按“目的—原理—关键操作—现象/数据—结论—误差与安全”复盘。"],"visualSummary":{"kind":"network","title":"实验操作先按目的选","center":"实验目的","groups":[{"label":"固液分离","items":["过滤/洗涤","蒸发/结晶"]},{"label":"互溶液体","items":["蒸馏/分馏","温度计位置","冷凝水下进上出"]},{"label":"不互溶液体","items":["萃取/分液","振荡放气","下层先放"]},{"label":"证据链","items":["装置/操作","现象→结论","误差与安全"]}]},"sections":[{"title":"先把常见仪器和操作补回","summary":"每个操作都对应一个目的。","items":[{"label":"测量仪器","rule":"量筒量取近似体积，滴定管精确放液，容量瓶配制固定体积，移液管移取准确体积。滴定管、移液管按要求用待装液润洗；容量瓶不能用待配溶液润洗。","examples":["【示范：配液—加热—过滤的仪器链】用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。"],"visualSteps":["测量仪器","选择测量仪器","规范加热","过滤洗涤","检查气密性"]},{"label":"加热与冷却","rule":"试管、烧杯、坩埚等加热方式不同；加热前检查装置，停止加热后防倒吸，热玻璃不能骤冷。","examples":["【示范：配液—加热—过滤的仪器链】用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。"],"visualSteps":["加热与冷却","选择测量仪器","规范加热","过滤洗涤","检查气密性"]},{"label":"过滤、洗涤、结晶","rule":"过滤分固液；洗涤除表面可溶杂质；蒸发浓缩—冷却结晶适合溶解度随温度变化明显的物质。","examples":["【示范：配液—加热—过滤的仪器链】用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。"],"visualSteps":["过滤、洗涤、结晶","选择测量仪器","规范加热","过滤洗涤","检查气密性"]},{"label":"气密性","rule":"形成密闭体系，通过压强变化产生气泡、液面差等现象判断；装药前完成。","examples":["【示范：配液—加热—过滤的仪器链】用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。"],"visualSteps":["气密性","选择测量仪器","规范加热","过滤洗涤","检查气密性"]}]},{"title":"气体制备装置链","summary":"从反应物状态和条件选发生装置。","items":[{"label":"发生","rule":"固—固加热、固—液不加热或液—液加热决定装置；需要控制速率时用滴液漏斗等。","examples":["【示范：制备干燥NH₃的装置链】发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。"],"visualSteps":["发生","发生","净化干燥","收集","尾气与安全"]},{"label":"净化与干燥","rule":"先除杂再干燥；洗气试剂不能消耗主体或引入新杂质，气体通常长管进。","examples":["【示范：制备干燥NH₃的装置链】发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。"],"visualSteps":["净化与干燥","发生","净化干燥","收集","尾气与安全"]},{"label":"收集","rule":"由气体密度、溶解性、是否与水/空气反应选择排水、向上或向下排空气。","examples":["【示范：制备干燥NH₃的装置链】发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。"],"visualSteps":["收集","发生","净化干燥","收集","尾气与安全"]},{"label":"尾气与防倒吸","rule":"有毒、刺激性气体要吸收；易溶气体吸收时设置安全瓶、倒扣漏斗等防倒吸。","examples":["【示范：制备干燥NH₃的装置链】发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。"],"visualSteps":["尾气与防倒吸","发生","净化干燥","收集","尾气与安全"]}]},{"title":"检验与性质探究","summary":"现象必须具有唯一或经排干扰后的指向。","items":[{"label":"检验三件套","rule":"写“取样—加试剂/操作—观察现象—得出检出结论”，不能只报试剂名。","examples":["【示范：检验SO₄²⁻的完整证据】取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。"],"visualSteps":["检验三件套","取样","排除干扰","现象","对照与结论边界"]},{"label":"排除干扰","rule":"先除去或掩蔽会产生相同现象的粒子；试剂加入顺序可能决定结论是否可靠。","examples":["【示范：检验SO₄²⁻的完整证据】取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。"],"visualSteps":["排除干扰","取样","排除干扰","现象","对照与结论边界"]},{"label":"控制变量","rule":"只改变研究因素，其余物质用量、浓度、温度、接触面积等保持一致。","examples":["【示范：检验SO₄²⁻的完整证据】取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。"],"visualSteps":["控制变量","取样","排除干扰","现象","对照与结论边界"]},{"label":"对照与空白","rule":"阳性对照证明体系能出现预期现象，空白对照排除试剂或装置本身造成的现象。","examples":["【示范：检验SO₄²⁻的完整证据】取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。"],"visualSteps":["对照与空白","取样","排除干扰","现象","对照与结论边界"]}]},{"title":"定量实验和数据处理","summary":"先建计算模型，再操作。","items":[{"label":"滴定","rule":"标准液浓度和体积通过方程式计量关系求待测量；平行测定剔除明显异常，取相近值平均。","examples":["【示范：滴定数据和误差方向】平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。"],"visualSteps":["滴定","记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]},{"label":"称量法/气体法","rule":"由沉淀质量、质量差或气体体积反推组分；要保证转化完全、产物组成明确。","examples":["【示范：滴定数据和误差方向】平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。"],"visualSteps":["称量法/气体法","记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]},{"label":"有效数字与记录","rule":"记录精度由仪器决定；中间保留足够位数，最终按要求表达。","examples":["【示范：滴定数据和误差方向】平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。"],"visualSteps":["有效数字与记录","记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]},{"label":"误差方向","rule":"沿“操作错误→直接测量量偏大/偏小→公式中分子分母→结果方向”推，不背孤立结论。","examples":["【示范：滴定数据和误差方向】平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。"],"visualSteps":["误差方向","记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]}]},{"title":"方案评价和开放设计","summary":"评价要指出问题、后果和改进。","items":[{"label":"可行性","rule":"反应能否发生、现象是否明显、仪器条件是否满足。","examples":["【示范：评价一个气体制备方案】依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。"],"visualSteps":["可行性","可行性","科学性","安全环保","简约准确"]},{"label":"科学性","rule":"变量是否唯一、证据是否充分、结论是否超范围、是否有重复验证。","examples":["【示范：评价一个气体制备方案】依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。"],"visualSteps":["科学性","可行性","科学性","安全环保","简约准确"]},{"label":"安全与环保","rule":"有毒、腐蚀、易燃、爆炸风险是否控制，废液和尾气是否处理。","examples":["【示范：评价一个气体制备方案】依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。"],"visualSteps":["安全与环保","可行性","科学性","安全环保","简约准确"]},{"label":"简约与准确","rule":"在保证可靠前提下步骤更少、误差更小、资源更省；不能为简化牺牲证据。","examples":["【示范：评价一个气体制备方案】依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。"],"visualSteps":["简约与准确","可行性","科学性","安全环保","简约准确"]}]},{"title":"蒸馏、分馏、萃取和分液：按物性选操作","summary":"先判断混合物是否互溶、沸点差和溶解度差，再选择装置；操作细节决定安全和分离效果。","items":[{"label":"蒸馏","rule":"蒸馏利用互溶液体沸点不同，或从溶液中蒸出易挥发组分。温度计水银球应位于蒸馏烧瓶支管口附近；冷凝水下口进、上口出；加入沸石并避免蒸干。","examples":["【示范：从含少量非挥发杂质的水中制蒸馏水】水蒸气经冷凝得到馏出液，非挥发杂质留在烧瓶；温度计测的是进入支管的蒸气温度，不应插入液面下。"],"visualSteps":["按沸点差选择","温度计对准支管","冷凝水下进上出","接收馏分不蒸干"]},{"label":"分馏","rule":"多种互溶液体沸点接近时，使用分馏柱进行多次汽化—冷凝，可提高不同沸点馏分的分离程度；各馏分仍可能是混合物。","examples":["【示范：石油分馏】原油先受热汽化，不同沸点范围的组分在分馏塔不同高度冷凝；这是物理分离，不能写成裂化或裂解反应。"],"visualSteps":["互溶多组分","分馏柱多次平衡","按沸点范围收集","馏分仍可能混合"],"caution":"分馏与裂化、裂解不同，后两者涉及化学键变化。"},{"label":"萃取","rule":"萃取剂应与原溶剂互不相溶、不与溶质反应，且目标溶质在其中溶解度更大。加入分液漏斗后振荡、适时放气、静置分层。","examples":["【示范：从溴水中萃取Br₂】按题给选择一种与水不互溶且能较好溶解Br₂的有机溶剂；振荡放气后静置，Br₂主要转入有机层。不能只凭颜色判断上下层。"],"visualSteps":["检查萃取剂条件","振荡并放气","静置分层","确认目标所在层"]},{"label":"分液","rule":"分液用于分开互不相溶的液层。先打开上口塞或使内外相通，再从下口放出下层液体；到界面时关闭活塞，上层液体从上口倒出。上下层由密度或取样验证。","examples":["【示范：分开水层和有机层】先查题给密度判断哪层在下；若信息不足，可取少量某层滴入水中观察是否相溶。下层从活塞放出，上层从漏斗上口倒出，避免交叉污染。"],"visualSteps":["确认两液互不相溶","判断上下层","下层由下口放","上层由上口倒"]}]},{"title":"必修实验①：定量配液、铁、硫","summary":"三项实验分别训练容量操作、物质性质证据和价态转化证据。","items":[{"label":"配制一定物质的量浓度的溶液","rule":"先由c、V计算溶质质量或储备液体积；固体路线为称量—溶解—冷却—转移—洗涤并合并—定容—摇匀—贴签。容量瓶只锁定最终体积，不能在瓶内直接溶解放热物或长期贮液。","examples":["【示范：配制250 mL NaCl溶液】称量并在烧杯中溶解，冷却后定量转移；烧杯和玻璃棒洗涤2～3次并把洗液并入容量瓶，距刻度1～2 cm改用胶头滴管，凹液面最低点与刻度相切。"],"visualSteps":["计算","溶解冷却","定量转移","定容摇匀"],"caution":"任何误差先落到n实际或V实际，再用c=n/V判断方向。"},{"label":"铁及其化合物的性质","rule":"围绕Fe、Fe²⁺、Fe³⁺和相应氢氧化物设计转化与检验。试剂、现象和结论要对应；制Fe(OH)₂需尽量隔绝O₂，检验Fe³⁺可用SCN⁻显色但要排除颜色和氧化还原干扰。","examples":["【示范：Fe²⁺沉淀的时间序列】Fe²⁺+2OH⁻=Fe(OH)₂↓，浅色沉淀很快经历灰绿色并最终转为红褐色Fe(OH)₃；用煮沸冷却的水或液封减少O₂，可验证其易被氧化。"],"visualSteps":["准备低氧体系","生成Fe(OH)₂","记录颜色随时间变化","用方程解释"]},{"label":"不同价态含硫物质的转化","rule":"选取−2、0、+4、+6价含硫物质，先标反应前后价态，再选择氧化剂或还原剂并用现象佐证。SO₂使酸性KMnO₄褪色体现还原性；SO₂与H₂S生成S体现归中。","examples":["【示范：SO₂与H₂S归中】SO₂中S由+4降到0，H₂S中S由−2升到0；电子守恒得SO₂+2H₂S=3S↓+2H₂O，淡黄色硫沉淀支持转化发生。"],"visualSteps":["标+4与−2","归中到0","电子守恒定1∶2","现象支持结论"],"caution":"SO₂有毒、刺激性，实验需通风并处理尾气。"}]},{"title":"必修实验②：粗盐、周期律、速率","summary":"用分离顺序、对照证据和单变量方法建立可靠结论。","items":[{"label":"用化学沉淀法去除粗盐中的杂质离子","rule":"先溶解并明确Mg²⁺、Ca²⁺、SO₄²⁻等杂质；用BaCl₂除SO₄²⁻、NaOH除Mg²⁺、Na₂CO₃除Ca²⁺和过量Ba²⁺，过滤后再用盐酸除过量OH⁻、CO₃²⁻，最后蒸发结晶。顺序必须保证新引入离子能被后续除去。","examples":["【示范：为什么Na₂CO₃在BaCl₂之后】若BaCl₂略过量，后加Na₂CO₃可把Ba²⁺转成BaCO₃一并过滤；若先加Na₂CO₃再加BaCl₂，新增Ba²⁺失去后续沉淀出口。"],"visualSteps":["列杂质与试剂","安排BaCl₂在前","过滤沉淀","酸化除剩余试剂"]},{"label":"同周期、同主族元素性质的递变","rule":"选能代表金属性或非金属性的可比实验，保持物质用量、浓度、温度和操作一致。结论只落到所比较元素及证据，再联系半径、核吸引和电子层数解释总体规律。","examples":["【示范：卤素置换比较非金属性】把Cl₂水分别加入含Br⁻、I⁻的溶液，结合有机层颜色等题给现象判断Cl₂能氧化Br⁻、I⁻；再与Br₂能否氧化Cl⁻/I⁻的证据组合，得到Cl、Br、I非金属性顺序。"],"visualSteps":["设置可比体系","记录置换现象","写氧化还原反应","归纳同族趋势"],"caution":"不能只凭单次反应快慢比较本质强弱；还要排除浓度、温度等因素。"},{"label":"化学反应速率的影响因素","rule":"每组实验只改变浓度、温度、催化剂或固体表面积中的一个因素，其余条件相同；用同一可观测终点所需时间或单位时间变化量比较速率，并设置重复。","examples":["【示范：浓度对速率的影响】用等体积、不同浓度的反应物，在相同温度下测达到同一浑浊程度的时间；浓度较大组时间较短，才可在本实验条件下支持“增大浓度使速率增大”。"],"visualSteps":["只改浓度","其余条件相同","同一终点计时","重复并比较"]}]},{"title":"必修实验③：原电池、分子模型、乙醇乙酸","summary":"把宏观现象连接到电子流、分子结构和官能团性质。","items":[{"label":"化学能转化成电能","rule":"选可自发发生的氧化还原反应，把氧化和还原分在两个电极；外电路传电子，电解质或盐桥传离子。记录电流方向、电极现象和溶液变化，并由两半反应相加核对总反应。","examples":["【示范：锌—铜原电池】Zn作负极：Zn−2e⁻=Zn²⁺；Cu电极为正极，若溶液含Cu²⁺则Cu²⁺+2e⁻=Cu。电子经导线由Zn流向Cu，盐桥离子迁移维持电中性。"],"visualSteps":["判断自发总反应","分写两极","画电子/离子通路","相加核对"]},{"label":"搭建球棍模型认识有机分子结构","rule":"按原子成键数和空间连接搭建甲烷、乙烯、乙炔或同分异构体模型；模型用来比较连接方式和空间取向，不代表真实原子大小、键长比例或电子云。","examples":["【示范：甲烷与乙烯模型】甲烷模型显示四个C—H键呈空间分布；乙烯中双键两端原子具有近似平面关系。先按结构式连原子，再从模型提取可观察的空间差异。"],"visualSteps":["读结构式","按成键数连接","观察空间关系","说明模型边界"]},{"label":"乙醇、乙酸的主要性质","rule":"围绕羟基和羧基安排可观察反应：乙醇可燃烧、被氧化并与乙酸酯化；乙酸显酸性，可与活泼金属、碱或碳酸氢盐反应。每个现象对应一种性质，不用气味作唯一证据。","examples":["【示范：乙酸与NaHCO₃】CH₃COOH+HCO₃⁻=CH₃COO⁻+CO₂↑+H₂O，持续放出能使澄清石灰水变浑浊的气体，支持羧酸酸性强于碳酸的相应级次。"],"visualSteps":["识别羧基","加入NaHCO₃","检验CO₂","结论落到酸性"],"caution":"乙醇易燃，乙酸有腐蚀/刺激性；控制用量、远离明火并规范闻气味。"}]},{"title":"选择性必修实验①：电镀、燃料电池、平衡移动","summary":"三项实验都要先画电子或平衡关系，再看现象。","items":[{"label":"简单的电镀实验","rule":"待镀件作阴极并彻底除油、除锈；镀层金属常作阳极，电解液含镀层金属离子。通电后阴极发生金属离子还原，控制电流、时间和表面清洁度影响镀层均匀性。","examples":["【示范：铁件镀铜】铁件接电源负极：Cu²⁺+2e⁻=Cu；铜片接正极：Cu−2e⁻=Cu²⁺。若铁件未清洁，镀层易斑驳或脱落，不能把表面问题误判成电极反应不存在。"],"visualSteps":["清洁待镀件","镀件接阴极","铜阳极补Cu²⁺","观察并评价镀层"]},{"label":"制作简单的燃料电池","rule":"燃料在阳极被氧化，氧化剂在阴极被还原；电极式必须服从酸性、碱性等电解质环境。用电压或小负载现象证明有电能输出，再把两极反应相加得到总反应。","examples":["【示范：碱性氢氧燃料电池】阳极H₂+2OH⁻−2e⁻=2H₂O，阴极O₂+2H₂O+4e⁻=4OH⁻；把阳极式乘2后相加，得到2H₂+O₂=2H₂O。"],"visualSteps":["辨燃料与氧化剂","按介质写两极","测电压/负载","相加得总反应"],"caution":"H₂、可燃液体与O₂体系须防泄漏、明火和短路，只按教材安全装置操作。"},{"label":"探究影响化学平衡移动的因素","rule":"先建立可逆体系并保留对照，再只改变某一物质浓度、温度或压强；记录即时变化与再平衡后的现象，区分“稀释造成的直接变浅”和真正的平衡移动。催化剂不改变平衡位置。","examples":["【示范：Fe³⁺与SCN⁻显色平衡】在同一初始体系分装后，一份加入少量Fe³⁺、一份加入少量SCN⁻、一份作对照；红色加深可支持平衡向生成配合物方向移动，但必须排除仅由体积或本底颜色造成的变化。"],"visualSteps":["建立并分装平衡体系","保留对照","只改一个条件","区分瞬时与再平衡"]}]},{"title":"选择性必修实验②：滴定、水解、配合物","summary":"用规范读数、空白/对照和证据边界提高可靠性。","items":[{"label":"强酸与强碱的中和滴定","rule":"滴定管查漏、洗涤并用待装液润洗，移取准确体积待测液，加入合适指示剂；近终点逐滴加入并充分振荡，记录初末读数，做平行测定并舍去明显异常值。计算基于酸碱计量关系和实际滴定体积。","examples":["【示范：盐酸滴定NaOH】达到相近终点颜色且平行体积接近后，用c(HCl)V(HCl)=c(NaOH)V(NaOH)求未知浓度。尖嘴起初有气泡、终点消失会使记录体积偏大。"],"visualSteps":["查漏润洗","准确移样","逐滴至终点","平行数据计算"]},{"label":"盐类水解的应用","rule":"用等浓度盐溶液和蒸馏水/相应强酸强碱盐作对照，测pH或观察指示剂颜色，再由离子与水的反应解释。比较时控制温度、浓度；结论是水解趋势和溶液酸碱性，不是“盐完全变成酸和碱”。","examples":["【示范：CH₃COONa与NH₄Cl】等浓度条件下，CH₃COO⁻+H₂O⇌CH₃COOH+OH⁻使溶液显碱性；NH₄⁺+H₂O⇌NH₃·H₂O+H⁺使溶液显酸性。"],"visualSteps":["配等浓度样品","测pH并设对照","写水解平衡","结论限定到酸碱性"]},{"label":"简单配合物的制备","rule":"先识别中心离子和配体，再按滴加顺序观察颜色或溶解度变化。现象只能支持配位环境改变；若无价态变化，不得误判为氧化还原。","examples":["【示范：Cu²⁺与过量NH₃】向Cu²⁺溶液滴加少量氨水可先出现浅蓝色沉淀，继续加入过量NH₃形成深蓝色含铜配离子。记录“少量—过量”的连续现象，并说明Cu仍为+2价。"],"visualSteps":["确认Cu²⁺中心","少量NH₃出现沉淀","过量形成深蓝配离子","核对价态不变"]}]},{"title":"选择性必修实验③：酯、官能团、糖类","summary":"有机实验先认官能团，再控制条件、排除交叉反应并规范安全。","items":[{"label":"乙酸乙酯的制备与性质","rule":"乙醇与乙酸在浓硫酸催化、加热条件下发生可逆酯化；用适当冷凝/收集装置并控制加热。产物可用饱和Na₂CO₃溶液洗涤以除去乙酸、溶解部分乙醇并降低酯的溶解损失，分层后分液。","examples":["【示范：酯化与净化】CH₃COOH+C₂H₅OH⇌CH₃COOC₂H₅+H₂O。粗产品加入饱和Na₂CO₃时有CO₂生成并出现分层；先辨上下层密度再分液，不能直接靠闻气味判纯度。"],"visualSteps":["混合并安全加热","可逆酯化","饱和Na₂CO₃洗涤","分层分液"],"caution":"浓硫酸、乙酸有腐蚀性，乙醇和酯易燃；禁止明火和直接凑近闻气味。"},{"label":"有机化合物中常见官能团的检验","rule":"按候选官能团选择证据：碳碳双键可使溴水或酸性KMnO₄在合适条件下褪色，醛基可发生银镜或与新制Cu(OH)₂加热生成砖红色Cu₂O，羧基可与NaHCO₃放CO₂。每种试剂都要考虑其他可反应结构。","examples":["【示范：检验醛基的条件链】取样后加入新制Cu(OH)₂，在碱性条件下加热；出现砖红色Cu₂O沉淀支持含可还原该试剂的结构。葡萄糖也呈阳性，所以不能直接下结论“样品一定是醛类”。"],"visualSteps":["列候选官能团","选检验试剂","满足规定条件","现象与结论不过界"]},{"label":"糖类的性质","rule":"葡萄糖具有还原性，可用银氨溶液或新制Cu(OH)₂检验；淀粉遇碘显蓝色；蔗糖本身通常无还原性，水解并中和酸后可检验生成的还原糖。对照组用来区分水解前后。","examples":["【示范：验证淀粉水解】淀粉与稀酸加热后，取一份用碘液检查淀粉是否减少；另一份先加碱中和酸，再加新制Cu(OH)₂并加热检验还原糖。两个证据分别回答“反应物减少”和“产物生成”。"],"visualSteps":["酸性加热水解","分样","碘检反应物","中和后检还原糖"],"caution":"银氨溶液现配现用，实验结束按教师要求立即处理，不能久置。"}]}],"workedExamples":[{"substance":"配液—加热—过滤的仪器链","path":"用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。","labels":["选择测量仪器","规范加热","过滤洗涤","检查气密性"]},{"substance":"制备干燥NH₃的装置链","path":"发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。","labels":["发生","净化干燥","收集","尾气与安全"]},{"substance":"检验SO₄²⁻的完整证据","path":"取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。","labels":["取样","排除干扰","现象","对照与结论边界"]},{"substance":"滴定数据和误差方向","path":"平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。","labels":["记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]},{"substance":"评价一个气体制备方案","path":"依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。","labels":["可行性","科学性","安全环保","简约准确"]},{"substance":"检验SO₄²⁻","path":"取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂溶液；若出现白色沉淀，可支持检出SO₄²⁻。若原样含Ag⁺等，还需考虑新增干扰。","labels":["取样","排干扰","加试剂","现象与边界"]},{"substance":"滴定读数偏差","path":"若滴定管尖嘴开始有气泡、结束时气泡消失，读出的标准液体积包含填充尖嘴的体积，读数偏大；由计算式判断待测浓度通常偏高。","labels":["先判V偏大","再看公式","结论方向"]},{"substance":"四种分离操作的选择树","path":"互溶液体先看沸点差：差较大可蒸馏，较接近且为多组分可分馏；互不相溶或可借助溶解度差转移溶质时先萃取，再用分液分层。","labels":["先判互溶性","再看沸点差","萃取转移","分液分层"]},{"substance":"溴水萃取—分液完整操作","path":"选择合适萃取剂，振荡并放气，静置分层；依据密度或取样确定目标层，先从下口放下层，再从上口倒出上层。每一步写出目的。","labels":["选剂","振荡放气","静置分层","规范分液"]},{"substance":"18项必做实验总索引","path":"必修9项与选择性必修9项逐项对应一张“目的—原理—操作—证据—结论—安全/误差”卡；复习时先定位实验名，再展开证据链。","labels":["定位实验","还原原理","复盘操作","检查证据边界"]},{"substance":"实验答案六格模板","path":"第一格写目的，第二格写反应/测量原理，第三格写关键操作与控制变量，第四格写现象或数据，第五格写不过界的结论，第六格写误差与安全。","labels":["目的","原理与操作","证据与结论","误差安全"]}],"checkpoints":["我能把实验答案写成完整证据链。","我会按发生—净化—收集—尾气处理检查装置。","我能设计单变量和对照实验。","我会从直接测量量推导误差方向。","我能由互溶性、沸点差和溶解度差选择蒸馏、分馏、萃取或分液。","我能指出蒸馏温度计和冷凝水方向，并规范写出分液操作。","我能说出课程标准18个必做实验的名称，并定位到对应展开卡。","我能为每个必做实验补全目的、原理、操作、证据、结论和安全/误差。","我会用对照、单变量和证据边界检查实验结论。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$curriculum_gap_h3_experiment$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_EXPERIMENT' and skill_id = 'H3_EXPERIMENT';

do $verify$
declare
  target_count integer;
  named_experiment_count integer;
  invalid_point_count integer;
begin
  select count(*) into target_count
  from public.chem_knowledge_cards
  where id in ('KC_H3_INORGANIC', 'KC_H3_EXPERIMENT')
    and review_status = 'approved'
    and coalesce((structured_content->>'version')::integer, 0) >= 2;

  select count(*) into named_experiment_count
  from public.chem_knowledge_cards c
  cross join lateral jsonb_array_elements(c.structured_content->'sections') s
  cross join lateral jsonb_array_elements(s->'items') i
  where c.id = 'KC_H3_EXPERIMENT'
    and i->>'label' = any(array['配制一定物质的量浓度的溶液','铁及其化合物的性质','不同价态含硫物质的转化','用化学沉淀法去除粗盐中的杂质离子','同周期、同主族元素性质的递变','化学反应速率的影响因素','化学能转化成电能','搭建球棍模型认识有机分子结构','乙醇、乙酸的主要性质','简单的电镀实验','制作简单的燃料电池','探究影响化学平衡移动的因素','强酸与强碱的中和滴定','盐类水解的应用','简单配合物的制备','乙酸乙酯的制备与性质','有机化合物中常见官能团的检验','糖类的性质']);

  select count(*) into invalid_point_count
  from public.chem_knowledge_cards c
  cross join lateral jsonb_array_elements(c.structured_content->'sections') s
  cross join lateral jsonb_array_elements(s->'items') i
  where c.id in ('KC_H3_INORGANIC', 'KC_H3_EXPERIMENT')
    and (
      jsonb_array_length(coalesce(i->'examples','[]'::jsonb)) = 0
      or jsonb_array_length(coalesce(i->'visualSteps','[]'::jsonb)) < 2
    );

  if target_count <> 2 then
    raise exception 'Expected two approved curriculum-gap cards, found %', target_count;
  end if;
  if named_experiment_count <> 18 then
    raise exception 'Expected 18 named mandatory experiments, found %', named_experiment_count;
  end if;
  if invalid_point_count <> 0 then
    raise exception 'Curriculum-gap points missing examples/visual steps: %', invalid_point_count;
  end if;
end
$verify$;

commit;
